import{_ as e,o as a,c as n,a2 as r}from"./chunks/framework.CHeM0PsO.js";const f=JSON.parse('{"title":"Data status glossary","description":"Definitions for current, delayed, stale, unavailable, reference-only, partial coverage, manual, connected, and read-only states shown across Zenin.","frontmatter":{"title":"Data status glossary","description":"Definitions for current, delayed, stale, unavailable, reference-only, partial coverage, manual, connected, and read-only states shown across Zenin.","audience":"user","status":"current","last_verified":"2026-07-19T00:00:00.000Z"},"headers":[],"relativePath":"use-zenin/data-status-glossary.md","filePath":"use-zenin/data-status-glossary.md","lastUpdated":null}'),s={name:"use-zenin/data-status-glossary.md"};function o(d,t,i,l,c,u){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="data-status-glossary" tabindex="-1">Data status glossary</h1><p>Zenin shows explicit status states instead of hiding gaps or inventing values. Use this glossary to interpret what you see.</p><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th><th>What to do</th></tr></thead><tbody><tr><td><strong>Current</strong></td><td>Recently refreshed from the source.</td><td>Trust as live within the source&#39;s normal cadence.</td></tr><tr><td><strong>Delayed</strong></td><td>The source provides data on a delay (for example, delayed quotes).</td><td>Treat as recent but not real-time.</td></tr><tr><td><strong>Stale</strong></td><td>The last successful refresh is older than expected.</td><td>Re-check the connection; data may be out of date.</td></tr><tr><td><strong>Unavailable</strong></td><td>The source did not return data.</td><td>Zenin shows the state; no value is fabricated.</td></tr><tr><td><strong>Reference-only</strong></td><td>Descriptive data (for example, fundamentals), not a live price.</td><td>Use for context, not valuation.</td></tr><tr><td><strong>Partial coverage</strong></td><td>The source returned some fields but not all.</td><td>Missing fields are left empty or marked, not guessed.</td></tr><tr><td><strong>Manual</strong></td><td>Entered by you, not imported from a connection.</td><td>Attributed as manual so it is not confused with connected data.</td></tr><tr><td><strong>Connected</strong></td><td>Imported from a read-only source you authorized.</td><td>Attributed to that source for traceability.</td></tr><tr><td><strong>Read-only</strong></td><td>The connection has no trade/withdraw permission.</td><td>Expected and required; Zenin rejects write-enabled keys.</td></tr></tbody></table><h2 id="why-states-matter" tabindex="-1">Why states matter</h2><p>A missing or delayed value is information. Zenin prefers to show <strong>delayed, stale, unavailable, or reference-only</strong> rather than manufacture a number it cannot source. When you see one of these states, check the source connection and the <a href="/get-started/troubleshooting-quickstart">troubleshooting quickstart</a>.</p><h2 id="related" tabindex="-1">Related</h2><ul><li><a href="/use-zenin/portfolio-and-connected-accounts">Portfolio and connected accounts</a> — how freshness and attribution appear per position.</li><li><a href="/get-started/connect-data-sources">Connect data sources</a> — read-only connection requirements.</li></ul>',7)])])}const g=e(s,[["render",o]]);export{f as __pageData,g as default};
